import json


def mirror_route_profile(profile_data: dict) -> dict:
    """Mirrors a route profile dictionary so that:

    - Coordinates and Altitude are even functions.
    - Gradient is an odd function.
    - Headings are adjusted by +180 degrees.
    - Distance continues monotonically forward.
    - The midpoint (last element of input) is not duplicated.
    """
    # Make a copy to avoid mutating the original input
    original = json.loads(json.dumps(profile_data))

    # Extract original arrays
    alt = original.get("Altitude", [])
    grad = original.get("Gradient", [])
    coords = original.get("Coordinates", [])
    dist = original.get("Distance", [])
    headings = original.get("Headings", [])
    speed_limit = original.get("SpeedLimit", [])
    speed_profile = original.get("SpeedProfile", [])

    n = len(dist)
    if n <= 1:
        return original

    # 1. Reverse arrays (excluding the last element to avoid duplicating the turnaround point)
    # Even functions: direct reversal
    mirrored_alt = alt[::-1][1:]
    mirrored_coords = coords[::-1][1:]
    mirrored_speed_limit = speed_limit[::-1][1:]
    mirrored_speed_profile = speed_profile[::-1][1:]

    # Odd function: negated reversal
    mirrored_grad = [-g for g in grad[::-1][1:]]

    # Headings: reverse and add 180 degrees (flip direction)
    mirrored_headings = [(h + 180.0) % 360.0 for h in headings[::-1][1:]]

    # Distance: calculate incremental step distances in reverse and extend forward
    total_dist = dist[-1]
    mirrored_dist = []
    for i in range(n - 1, 0, -1):
        step_delta = dist[i] - dist[i - 1]
        total_dist += step_delta
        mirrored_dist.append(total_dist)

    # 2. Combine original and mirrored sequences
    mirrored_profile = {
        "Altitude": alt + mirrored_alt,
        "Gradient": grad + mirrored_grad,
        "Coordinates": coords + mirrored_coords,
        "Distance": dist + mirrored_dist,
        "SpeedLimit": speed_limit + mirrored_speed_limit,
        "SpeedProfile": speed_profile + mirrored_speed_profile,
        "Headings": headings + mirrored_headings,
        "SolarIrradiance": original.get("SolarIrradiance", {}),
    }

    return mirrored_profile


